   458	                        mPrimaryInterface->leave_multicast_address(&iter->first);
   459	                        mMulticastAddresses.erase(iter);
   460	                        did_remove = true;
   461	                        break;
   462	                }
   463	        } while (did_remove);
   464	
   465	        // On-Mesh Prefixes
   466	        do {
   467	                std::multimap<IPv6Prefix, OnMeshPrefixEntry>::iterator iter;
   468	
   469	                did_remove = false;
   470	
   471	                for (iter = mOnMeshPrefixes.begin(); iter != mOnMeshPrefixes.end(); iter++) {
   472	                        if (!iter->second.is_from_ncp()) {
   473	                                continue;
   474	                        }
   475	
   476	                        syslog(LOG_INFO, "OnMeshPrefixes: Removing %s", iter->second.get_description(iter->first).c_str());
   477	                        mOnMeshPrefixes.erase(iter);
   478	                        did_remove = true;
   479	                        break;
   480	                }
   481	        } while (did_remove);
   482	
   483	        // Off-Mesh Routes
   484	        do {
   485	                std::multimap<IPv6Prefix, OffMeshRouteEntry>::iterator iter;
   486	
   487	                did_remove = false;
   488	
   489	                for (iter = mOffMeshRoutes.begin(); iter != mOffMeshRoutes.end(); iter++) {
   490	                        if (!iter->second.is_from_ncp()) {
   491	                                continue;
   492	                        }
   493	
   494	                        syslog(LOG_INFO, "OffMeshRoutes: Removing %s", iter->second.get_description(iter->first).c_str());
   495	                        mOffMeshRoutes.erase(iter);
   496	                        did_remove = true;
   497	                        mRequestRouteRefresh = true;
   498	                        break;
   499	                }
   500	        } while (did_remove);
   501	}
